//! The acceptance pair for generating a published pack from its typed N Lang source.
//!
//! `recording_consent` is the only domain this repository ships BOTH ways — a typed Snapp
//! source and a published `.r14n.toml` — so it is the only place where "the published
//! artifact is generated, not hand-maintained" can be proved. `docs/evidence/toml-export/`
//! states what the generated bytes would have to be; this file is what keeps that statement
//! from rotting into a second, stale source of truth.
//!
//! It deliberately does NOT run an exporter. None exists yet, and N Lang is proprietary so
//! public CI could not invoke it anyway (see `AGENTS.md`). What it CAN do is hold the
//! expected output pinned to the published pack, and pin the shape gap between the emitted
//! bundle and the published form — which is the thing that decides how much an exporter has
//! to know about RLPS packs.
//!
//! Style note: FQ paths, no module-top `use` — the house style of this tree.

fn root() -> ::std::path::PathBuf {
  ::std::path::Path::new(::std::env!("CARGO_MANIFEST_DIR")).join("..")
}

fn read(rel: &str) -> ::std::string::String {
  let p = root().join(rel);
  ::std::fs::read_to_string(&p).unwrap_or_else(|e| ::std::panic!("read {}: {e}", p.display()))
}

/// The published pack with every comment and every run of blank lines removed — the exact
/// transformation `docs/evidence/toml-export/expected/` is defined as.
///
/// `#` is only a comment opener OUTSIDE a string. No pack carries one inside a string today,
/// but a serializer-generated description eventually will, and a truncation there would
/// silently drop half a value rather than a comment.
fn non_comment_body(src: &str) -> ::std::string::String {
  let mut out = ::std::string::String::new();
  let mut pending_blank = false;
  let mut seen = false;
  for line in src.lines() {
    let mut in_string = false;
    let mut cut = line.len();
    for (i, c) in line.char_indices() {
      match c {
        '"' => in_string = !in_string,
        '#' if !in_string => {
          cut = i;
          break;
        }
        _ => {}
      }
    }
    let trimmed = line[..cut].trim_end();
    if trimmed.is_empty() {
      pending_blank = true;
      continue;
    }
    if pending_blank && seen {
      out.push('\n');
    }
    pending_blank = false;
    seen = true;
    out.push_str(trimmed);
    out.push('\n');
  }
  out
}

const PROFILES: [&str; 2] = ["aggressive", "minimal"];

/// Why: an expected-output fixture that nothing re-derives is a second source of truth, and
/// this repository has already shipped one of those — `health_aggressive` was authored twice
/// and the copies drifted apart unnoticed for weeks, because the posture they disagreed under
/// hid the disagreement. A fixture committed beside the artifact it describes is the same
/// trap, so it is regenerated and compared on every run instead of being trusted.
#[test]
fn every_expected_fixture_is_its_published_packs_non_comment_body() {
  for profile in PROFILES {
    let published = read(&::std::format!("packs/{profile}/recording_consent.r14n.toml"));
    let fixture = read(&::std::format!(
      "docs/evidence/toml-export/expected/recording_consent.{profile}.toml"
    ));
    ::std::assert_eq!(
      non_comment_body(&published),
      fixture,
      "docs/evidence/toml-export/expected/recording_consent.{profile}.toml has drifted from \
       packs/{profile}/recording_consent.r14n.toml. The fixture is DERIVED — regenerate it \
       from the pack rather than editing it, or the acceptance pair names an output no \
       published artifact has."
    );
  }
}

/// Why: the acceptance is stated as VALUE equality, not byte equality, because the two
/// published packs disagree on table order (`aggressive` puts `[legally_required]` last,
/// `minimal` puts it first) and a serializer emits one order. If stripping comments ever
/// changed a VALUE rather than just presentation, the acceptance would be quietly wrong in
/// the direction that matters, so the comparison is made on the parsed trees too.
#[test]
fn stripping_comments_changes_no_value_in_any_published_pack() {
  for profile in PROFILES {
    let published = read(&::std::format!("packs/{profile}/recording_consent.r14n.toml"));
    let fixture = read(&::std::format!(
      "docs/evidence/toml-export/expected/recording_consent.{profile}.toml"
    ));
    let a: ::toml::Value = ::toml::from_str(&published)
      .unwrap_or_else(|e| ::std::panic!("packs/{profile}/recording_consent.r14n.toml: {e}"));
    let b: ::toml::Value = ::toml::from_str(&fixture)
      .unwrap_or_else(|e| ::std::panic!("expected/recording_consent.{profile}.toml: {e}"));
    ::std::assert_eq!(a, b, "the {profile} fixture and its published pack differ in VALUE");
  }
}

/// Why: the emitted keyword-form node now IS a published pack, and this proves it against
/// the published schema rather than against a hand-list of field names.
///
/// This test replaced an inverted tripwire that asserted the opposite. Until 2026-10-16 the
/// framework type spelled the subject table `subjects` and emitted `legally_required` as a
/// bare list, so a STRAIGHT serialization of the emitted tree was not a valid pack and some
/// consumer had to rename and wrap on the way out. The tripwire existed to go red the moment
/// someone fixed the type — which is what happened, and this is the replacement.
///
/// `domain` is the one key the published schema does not allow at top level, and it stays in
/// the typed source deliberately: a bundle holds MANY packs, and `domain` is what names the
/// file each one splits into. Deriving it from the bundle key instead would be a projection
/// again, and one built on a convention the two repositories do not share (here the keys read
/// `RECORDING_CONSENT_AGGRESSIVE`, downstream they read `CONTACT_IMPORT`). So the writer drops
/// ONE key, which is a deletion a serializer can do without knowing what an RLPS pack is —
/// not a shape projection. Whether `domain` should simply become an optional schema property
/// is a governance question (additive, but it changes a published schema), not a lane one.
#[test]
fn every_emitted_keyword_pack_validates_against_the_published_schema() {
  let bundle: ::serde_json::Value =
    ::serde_json::from_str(&read("snapp/r14n_baselines@1.0.0.json"))
      .expect("baselines bundle is not valid JSON");
  let schema: ::serde_json::Value =
    ::serde_json::from_str(&read("schema/pack.schema.json")).expect("pack schema");
  let validator = ::jsonschema::draft202012::options()
    .build(&schema)
    .expect("schema/pack.schema.json is not a valid Draft 2020-12 schema");

  let packs = bundle["policies"].as_object().expect("bundle has no `policies` object");
  ::std::assert!(!packs.is_empty(), "no emitted packs — the glob or the export is wrong");

  let mut checked = 0usize;
  for (name, node) in packs {
    let mut pack = node.clone();
    let removed = pack
      .as_object_mut()
      .expect("a pack node is an object")
      .remove("domain");
    ::std::assert!(
      removed.is_some(),
      "{name} carries no `domain`, so nothing can name the file it splits into"
    );

    let errors: ::std::vec::Vec<::std::string::String> =
      validator.iter_errors(&pack).map(|e| ::std::format!("{} at {}", e, e.instance_path)).collect();
    ::std::assert!(
      errors.is_empty(),
      "{name} does not validate against the published pack schema: {errors:?}"
    );
    checked += 1;
  }
  ::std::assert!(checked > 0, "validated nothing");
}

/// Why: the whole point of the rename is that NO consumer has to rename or wrap on the way
/// out, and the way that regresses is someone reintroducing the plural or unwrapping the
/// floor in the typed source. Asserted on the emitted bytes, which is the only place the
/// claim is observable — the type declaration could say anything.
#[test]
fn the_emitted_shape_needs_no_rename_and_no_wrapping() {
  let bundle: ::serde_json::Value =
    ::serde_json::from_str(&read("snapp/r14n_baselines@1.0.0.json"))
      .expect("baselines bundle is not valid JSON");
  for (name, pack) in bundle["policies"].as_object().expect("policies") {
    ::std::assert!(
      pack.get("subjects").is_none(),
      "{name} emitted the PLURAL `subjects` again — the published schema spells it `subject`, \
       and a consumer would have to rename it back"
    );
    ::std::assert!(
      pack["subject"].is_object(),
      "{name}: `subject` must be a keyed map of control lists, as the schema specifies"
    );
    ::std::assert!(
      pack["legally_required"]["controls"].is_array(),
      "{name}: `legally_required` lost its `controls` wrapper — the published pack spells it \
       `[legally_required] controls = [...]`"
    );
  }
}
